"""PLA — K. Ekran Şablonları (Pinterest panosundaki ekranların PluginLabs dilinde tam kompozisyonları)"""
from advanced import add, I, poly, smooth, area, ecg, bars

K = "Ekran Şablonları"
def rail(active=0, items=("grid","film","calendar","bell","settings"), logo="PL"):
    out = [f'<nav class="pl-rail" aria-label="Gezinme"><span class="pl-rail__logo">{logo}</span>']
    for i, ic in enumerate(items[:-1]):
        out.append(f'<button class="pl-rail__item{" is-active" if i==active else ""}" aria-label="{ic}">{I(ic,20)}</button>')
    out.append(f'<span class="pl-rail__spacer"></span><button class="pl-rail__item" aria-label="{items[-1]}">{I(items[-1],20)}</button></nav>')
    return "".join(out)

